// === CONFIGURATION ===
// Add your GitHub repos containing skills here
const SKILLS_REPOS = [
  { owner: 'YOUR_GITHUB_USERNAME', repo: 'business-memory-skills' }
];

const allDirs = [];

for (const { owner, repo } of SKILLS_REPOS) {
  // List root contents
  const rootUrl = `https://api.github.com/repos/${owner}/${repo}/contents/`;
  const rootResp = await this.helpers.httpRequest({
    method: 'GET',
    url: rootUrl,
    headers: {
      'Accept': 'application/vnd.github.v3+json',
      'User-Agent': 'n8n-skills-agent'
    }
  });

  // Find the skills directory
  const skillsDir = rootResp.find(item => item.name === 'skills' && item.type === 'dir');

  if (skillsDir) {
    // List contents of /skills/
    const skillsUrl = `https://api.github.com/repos/${owner}/${repo}/contents/skills/`;
    const skillsResp = await this.helpers.httpRequest({
      method: 'GET',
      url: skillsUrl,
      headers: {
        'Accept': 'application/vnd.github.v3+json',
        'User-Agent': 'n8n-skills-agent'
      }
    });

    for (const item of skillsResp) {
      if (item.type === 'dir') {
        allDirs.push({
          repo: `${owner}/${repo}`,
          skill: item.name,
          path: `skills/${item.name}/SKILL.md`
        });
      }
    }
  }
}

// Build the directory map for the agent's system prompt
const directoryMap = allDirs.map(d => `- **${d.skill}** → \`${d.repo}/${d.path}\``).join('\n');

return [{
  json: {
    directoryMap,
    skillsList: allDirs
  }
}];
